Begin ColonyMineDoor

;enables door and controls entry to mine during quest CO_2


if ( GetDisabled == 0 )
	if ( ColonyState < 1 )
		Disable
	endif
endif

if ( GetDisabled == 1 )
	if ( ColonyState >= 2 )
		Enable
	endif
endif

if ( GetJournalIndex CO_2 >= 10 )
	if ( GetJournalIndex CO_2 < 50 )
		if ( GetDistance "Hroldar the Strange" <= 256 )
			If ( OnActivate == 1 )
				MessageBox "문을 열 수 없습니다. 흐롤다르가 길을 막고 있습니다."
			endif
		endif
	endif
endif

if ( GetJournalIndex CO_2 >= 50 )
	if ( OnActivate == 1 )
		Activate
	endif
endif

End ColonyDoorMine

begin denegorScript

short message
short journal
short death
short nolore

if ( MenuMode == 1 )
	Return
endif

if ( GetJournalIndex MS_Bouncer = 0 )
	return
endif


if ( GetHealth <= 100 )
	if ( message == 0 )
		if ( GetDeadCount Hession < 1 )
			MessageBox "헷시온-제발 아무도 죽이지 마세요! 필요하다면 기절시키되, 죽이지는 마세요!"
			set message to 1
		endif
	endif
endif

if ( OnKnockout == 1 )
	if ( journal == 0 )
		SetFatigue 0
		set journal to 1
	endif
endif

if ( journal == 1 )
	if ( GetDeadCount Hession < 1 )
		Journal "MS_Bouncer" 30
		set journal to 2
	endif
endif

if ( journal >= 1 )
	if ( CellChanged == 1 )
		disable
	endif
endif

if ( OnDeath == 1 )
	if ( death == 0 )
		if ( GetDeadCount Hession < 1 )
			Journal "MS_Bouncer" 40
			set death to 1
		endif
		set hession.HessDeath to 1
	endif
endif

End

Begin pillowScript

short comfy

if ( PCVampire == 1 )
	return
endif

if ( comfy == -1 )
	if ( player->GetItemCount "misc_uni_pillow_unique" > 0 )
		if ( GetPCSleep == 0 )
			set comfy to 0
			return
		endif
	endif
endif


if ( comfy == 0 )
	if ( player->GetItemCount "misc_uni_pillow_unique" > 0 )
		if ( GetPCSleep == 1 )
			MessageBox "아주 편안한 베개 덕분에 푹 잤습니다."
			set comfy to -1
			return
		endif
	endif
endif


End pillowScript

Begin stoneUlfgarScript

if ( menumode == 1 )
	return
endif

if ( GetJournalIndex "BM_BrodirGrove" < 90 )
	Disable
endif

if ( GetJournalIndex "BM_BrodirGrove" >= 90 )
		Enable
endif


if ( GetJournalIndex BM_BrodirGrove < 90 )
	return
endif


if ( OnActivate == 1 )
	if ( GetJournalIndex BM_BrodirGrove >= 10 )
		Cast "stone_ulfgar" Player					;fortify strength 10
		MessageBox "울프가르의 힘을 부여받았습니다."
	endif
endif

end
